"""Explain generated return types, order variants, names and pointer arguments."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1573': ('답안지에는 숫자를 쓰는 칸도 있고 “네·아니요”를 고르는 칸도 있어요. 함수도 어떤 종류의 답을 돌려주는지 먼저 정해야 해요.', '생성기가 반환 자료형을 고르는 규칙과 실제 계산을 구별합니다.', 'meta B·R·v와 기본 정수 long을 적으세요. 출력 자료형을 각각 bool·long·void로 연결하세요.', ['반환은 함수가 호출한 쪽에 답을 돌려주는 일이에요. 반환 자료형은 그 답이 숫자인지 참·거짓인지 등을 나타내요. gen_ret_type은 이 자료형을 뜻하는 글자를 출력하는 쉘 함수예요.', '첫 입력 meta는 만들 함수의 종류를 나타내는 문자예요. s 또는 v이면 void를 출력해요. void는 돌려주는 값이 없다는 뜻이며 숫자 0을 반환한다는 뜻은 아니에요.', 'b 또는 B이면 bool을 출력해요. bool은 true와 false, 즉 참과 거짓을 담는 자료형이에요. 기본 정수로 long을 전달했더라도 이 분기는 long이 아니라 bool을 골라요.', 'R처럼 정수를 반환하는 분류이면 호출자가 지정한 기본 정수 이름을 출력해요. 기본 이름이 long이면 long, s64이면 s64예요. 같은 생성 규칙을 서로 다른 원자 정수 계열에 재사용할 수 있는 이유예요.', 'R은 갱신 뒤 숫자를, fetch 계열은 갱신 전 숫자를 돌려주지만 둘 다 long 같은 같은 자료형일 수 있어요. 자료형만 읽어서는 그 숫자의 뜻을 다 알 수 없어요. 표의 분류와 함수 설명도 함께 읽어야 해요.', 'gen_ret_stmt는 값을 반환하는 분류인지 확인해 생성 코드에 return 글자를 넣어요. 생성기가 long이나 return을 출력하는 시점에는 아직 원자 덧셈을 실행하는 것이 아니에요. 나중에 컴파일될 C 코드를 만드는 단계예요.'], [('meta가 B이면 gen_ret_type이 출력하는 반환 자료형은 무엇인가요?', ['기본 정수와 관계없이 언제나 long이에요', '참·거짓을 담는 bool이에요'], '정답은 두 번째예요. case의 b·B 갈래가 bool을 직접 출력해요. 기본 정수 이름은 정수 반환 분류에서 쓰이므로 모든 분류가 long이 되는 것은 아니에요.'), ('meta R과 기본 정수 이름 long을 넘기면 어떤 반환 자료형을 만드나요?', ['long이에요', '반환값이 없는 void예요'], '정답은 첫 번째예요. R은 계산 뒤 숫자를 반환하는 계열이라 지정된 정수 자료형을 써요. void를 고르는 s·v와 구별하세요.')]), 'os1574': ('같은 이름표에도 필요한 꼬리표만 붙여요. 읽기 함수에는 읽기용 순서 이름을, 저장 함수에는 저장용 순서 이름을 붙이는 규칙을 따라가 봅시다.', '읽기와 저장에서 생성되는 순서 변형이 다른 이유를 읽습니다.', 'read l → read·read_acquire, set s → set·set_release를 적으세요. 각 기본 함수의 순서 약속은 relaxed라고 표시하세요.', ['gen_proto_order_variants는 기본 함수를 먼저 만든 뒤 추가로 만들 순서 변형을 고르는 함수예요. variant는 같은 계열에서 이름이나 약속이 조금 다른 형태라는 뜻이에요.', 'meta l은 load, 즉 읽기예요. acquire 분류에는 l이 있으므로 read_acquire를 추가해요. release나 relaxed 추가 분류에는 l이 없으므로 read_release나 별도 read_relaxed를 이 규칙에서 만들지 않아요.', 'meta s는 store, 즉 저장이에요. release 분류에는 s가 있으므로 set_release를 추가해요. acquire 추가 분류에는 s가 없어서 set_acquire를 만들지 않아요. 읽기와 저장에 대칭으로 모든 이름을 붙이지 않는다는 점이 중요해요.', 'B·F·I·R은 acquire·release·relaxed 분류에 모두 들어 있어요. 그래서 각각 기본 형태에 세 가지 순서 형태를 더해 네 개가 돼요. 생성 여부는 문자 집합을 검사하는 함수들이 결정해요.', '기본 이름에 _relaxed가 없다고 반드시 full ordering은 아니에요. meta_is_implicitly_relaxed는 v·l·s의 기본 형태를 relaxed로 설명하게 해요. 따라서 기본 read와 set도 relaxed예요.', '순서 이름은 다른 메모리 접근에 대해 어떤 약속을 주는지를 표시해요. 이름이 그럴듯하다고 함수를 만들어 추측하지 말고 생성 분류와 실제 헤더를 확인하세요. 이 반복은 C 함수 글자를 만드는 일이지 읽기나 저장을 그 자리에서 실행하는 일이 아니에요.'], [('읽기를 뜻하는 meta l에서 추가하는 명시적 순서 형태는 무엇인가요?', ['read_release예요', 'read_acquire예요'], '정답은 두 번째예요. l은 acquire를 만드는 분류에 들어 있고 release 분류에는 없어요. 읽기와 저장의 생성 목록은 달라요.'), ('저장을 뜻하는 meta s에서 추가하는 명시적 순서 형태는 무엇인가요?', ['set_release예요', 'set_acquire예요'], '정답은 첫 번째예요. s는 release 분류에 들어 있어요. 기본 set도 만들지만 그 기본 순서 약속은 relaxed이므로 별도 이름이 없다고 full이라고 판단하면 안 돼요.')]), 'os1575': ('세 가지 상품에 선택 사항을 붙이면 상품 이름이 세 개보다 많아질 수 있어요. add의 v·R·F도 각각 필요한 순서 형태까지 펼쳐서 세어야 해요.', 'meta 문자 반복으로 만드는 함수 이름과 개수를 계산합니다.', 'v는 1개, R은 기본·acquire·release·relaxed 4개, F도 4개를 그려 1+4+4=9를 계산하세요.', ['gen_proto는 vRF 같은 문자열을 한 문자씩 나눠요. 여기의 grep -o .는 문자를 하나씩 꺼내는 데 쓰여요. 반복문은 v, R, F 각각을 gen_proto_variants에 넘겨요.', 'prefix는 이름 앞에 붙이는 글자예요. f 또는 F이면 fetch_라는 prefix를 붙여요. add에 붙이면 fetch_add가 되어 계산 전 값을 돌려주는 계열임을 나타내요.', 'suffix는 이름 뒤에 붙이는 글자예요. R이면 _return을 붙여 add_return을 만들어요. 이 계열은 계산 뒤 값을 돌려줘요. v에는 fetch_나 _return을 붙이지 않아 기본 add가 돼요.', '그다음 순서 변형을 펼쳐요. v의 add는 하나예요. R은 add_return과 뒤에 _acquire·_release·_relaxed가 붙는 형태까지 네 개예요. F도 fetch_add와 같은 세 꼬리표까지 네 개예요.', '따라서 atomic-long 생성기의 add vRF는 1+4+4=9개의 wrapper를 만들어요. wrapper는 호출을 안쪽 함수에 전달하는 C 함수예요. 실제 헤더에서는 raw_atomic_long_이라는 계열 이름도 앞에 붙어 있어요.', '함수 종류가 아홉 개라는 말은 덧셈 한 번을 호출할 때 아홉 번 더한다는 뜻이 아니에요. 생성 단계에서 선택 가능한 입구들을 미리 만든 것이에요. 실행하는 코드는 필요한 형태 하나를 골라 불러요.'], [('add vRF를 순서 변형까지 펼치면 이 long 생성기는 wrapper를 몇 개 만드나요?', ['v·R·F가 세 글자라서 3개만 만들어요', 'v 1개, R 4개, F 4개로 모두 9개예요'], '정답은 두 번째예요. R과 F에는 기본 형태 외에 세 가지 순서 형태가 더 있어요. 문자 수만 세면 추가 변형을 놓쳐요. 9개 생성은 실행 때 덧셈을 9번 한다는 뜻이 아니에요.'), ('함수 이름 앞에 fetch_를 붙이는 meta는 무엇인가요?', ['f와 F예요', 'v와 s예요'], '정답은 첫 번째예요. gen_proto_variants가 f·F인지 검사해 앞부분 이름을 정해요. v는 반환 없는 형태이고 s는 저장 분류라서 fetch_를 붙이는 조건이 아니에요.')]), 'os1576': ('숫자 자체를 주는 것과 숫자가 적힌 공책의 위치를 알려 주는 것은 달라요. 위치를 받으면 그곳을 읽거나 규칙에 따라 내용을 고칠 수 있어요.', '인자 생성 규칙에서 값·포인터·const의 차이를 이해합니다.', '기본 long·atomic_long으로 i → long, p:old → long *, v → atomic_long_t *, cv → const atomic_long_t *를 적으세요.', ['인자는 함수를 부를 때 건네는 정보예요. i는 정수값 자체, p는 정수가 놓인 위치를 가리키는 포인터예요. 기본 정수 이름이 long이면 각각 long과 long *를 만들어요. 별표 *가 포인터를 나타내요.', 'v는 원자 객체를 가리키는 포인터예요. 원자 계열 이름이 atomic_long이면 atomic_long_t *를 만들어요. 일반 정수의 포인터 p와 원자 객체의 포인터 v를 같은 것으로 읽지 마세요.', 'cv는 const atomic_long_t *가 돼요. const는 이 포인터를 통해 대상 객체를 수정하지 않는다는 제한이에요. 다른 경로에서 값이 바뀌지 않는다는 약속이나 객체를 영원히 고정하는 잠금은 아니에요.', 'const atomic_long_t *와 atomic_long_t * const는 달라요. 앞의 것은 가리킨 대상을 이 포인터로 바꾸지 않는다는 뜻이고, 뒤의 것은 포인터 변수 자체가 다른 위치를 가리키도록 바꾸지 못한다는 뜻이에요. const가 어디에 붙는지 보세요.', 'p:old에서 콜론 앞 p는 타입, 뒤 old는 이름이에요. gen_param_type은 콜론 뒤 이름을 떼고 타입을 고르므로 long *가 나와요. 나중에 이름을 붙이면 long *old가 돼요. try_cmpxchg는 이 위치를 받아 실패 때 예상 값 메모를 고칠 수 있어요.', '포인터 타입을 만들었다고 대상 자료의 수명이 확보되지는 않아요. 위치가 올바른지, 자료가 아직 존재하는지, 다른 작업과 함께 접근해도 되는지는 따로 지켜야 해요. 생성기는 C 선언의 글자를 맞추며 그런 실행 조건을 대신 보장하지 않아요.'], [('cv와 기본 계열 atomic_long으로 만드는 타입은 무엇인가요?', ['atomic_long_t * const로 포인터 자체를 고정해요', 'const atomic_long_t *로 이 포인터를 통한 대상 수정을 제한해요'], '정답은 두 번째예요. 생성 코드가 const를 atomic_long_t 앞에 붙여요. 포인터 자체를 고정하는 첫 번째 선언과 위치도 뜻도 달라요.'), ('p:old와 기본 정수 long으로 만드는 타입은 무엇인가요?', ['정수 위치를 가리키는 long *예요', '정수값 자체인 long이에요'], '정답은 첫 번째예요. p가 포인터 분류이고 old는 인자 이름이에요. 값만 받으면 호출자의 메모를 그 위치에서 고칠 수 없으므로 값과 위치를 구별해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_389.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
